package zeldaCV.model;

import java.time.LocalDateTime;

import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;
import lombok.ToString;

/**
 * A guestbook message. There are no user accounts: the author proves ownership with a random
 * password generated by their browser, of which only the SHA-256 hash is stored.
 * Schema is managed by Flyway (db/migration).
 */
@Entity
@Table(name = "comment")
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@ToString(exclude = "passwordHash")
public class CommentEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "pseudo", nullable = false, length = 20)
    private String pseudo;

    @Column(name = "comment", nullable = false, length = 250)
    private String comment;

    @Column(name = "coordinate_x", nullable = false)
    private int coordinateX;

    @Column(name = "coordinate_y", nullable = false)
    private int coordinateY;

    /** Creation date, in UTC. Also starts the 7-day edit window. */
    @Column(name = "created_at", nullable = false)
    private LocalDateTime createdAt;

    @Column(name = "password_hash", nullable = false, length = 64)
    private String passwordHash;
}
